test('windows 09:00 to 11:00 and 10:30 to 12:00 overlap by 30 minutes', function () {
  assert.deepEqual(code.windowOverlap({ start: '09:00', end: '11:00' }, { start: '10:30', end: '12:00' }), { overlaps: true, minutes: 30 });
});

test('windows that only touch at 12:00 do not overlap', function () {
  assert.deepEqual(code.windowOverlap({ start: '09:00', end: '12:00' }, { start: '12:00', end: '13:00' }), { overlaps: false, minutes: 0 });
});

test('swapped windows 10:30 to 12:00 and 09:00 to 11:00 overlap by 30 minutes', function () {
  assert.deepEqual(code.windowOverlap({ start: '10:30', end: '12:00' }, { start: '09:00', end: '11:00' }), { overlaps: true, minutes: 30 });
});

test('swapped windows that only touch at 12:00 do not overlap', function () {
  assert.deepEqual(code.windowOverlap({ start: '12:00', end: '13:00' }, { start: '09:00', end: '12:00' }), { overlaps: false, minutes: 0 });
});

test('windows that share one minute overlap by 1 minute', function () {
  assert.deepEqual(code.windowOverlap({ start: '09:00', end: '10:00' }, { start: '09:59', end: '11:30' }), { overlaps: true, minutes: 1 });
});

test('windows one minute apart do not overlap', function () {
  assert.deepEqual(code.windowOverlap({ start: '09:00', end: '10:00' }, { start: '10:01', end: '11:17' }), { overlaps: false, minutes: 0 });
});

test('a window fully inside another overlaps by 90 minutes', function () {
  assert.deepEqual(code.windowOverlap({ start: '08:00', end: '14:00' }, { start: '10:15', end: '11:45' }), { overlaps: true, minutes: 90 });
});

test('an inner window given first still overlaps by 90 minutes', function () {
  assert.deepEqual(code.windowOverlap({ start: '10:15', end: '11:45' }, { start: '08:00', end: '14:00' }), { overlaps: true, minutes: 90 });
});

